    });
    console.error();
    process.exit(1);
  }

  let addrInfo = addrInfos[0];
  let address = addrInfo.address || addrInfo.addr;
  let wifInfo = await wallet.findWif(addrInfo);

  if (!wifPath) {
    wifPath = ".";
  }

  let showAddr = true;
  let fullPath;
  let stat = await Fs.stat(wifPath).catch(function (err) {
    if ("ENOENT" === err.code) {
      return null;
    }
    throw err;
  });
  if (!stat) {
    fullPath = wifPath;
